const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),z=require('node:zlib'),crypto=require('node:crypto'),vm=require('node:vm');
const folder='docs/nationwide-expansion-20261020/',read=f=>JSON.parse(f.endsWith('.gz')?z.gunzipSync(fs.readFileSync(folder+f)):fs.readFileSync(folder+f)),manifest=read('manifest.json.gz'),evidence=read('source-evidence.json.gz'),photos=read('selected-photos.json.gz'),routeProof=read('route-proof.json'),E=require('../place-evidence.js'),C=require('../place-conditions.js'),P=require('../place-photos.js'),CP=require('../course-photos.js'),Pet=require('../course-pet-access.js');
test('539 new places retain source identities, commercially reusable photos and condition boundaries',()=>{
 assert.equal(manifest.facilities.length,539);assert.equal(evidence.length,539);assert.equal(photos.length,539);assert.equal(new Set(manifest.facilities.map(r=>r.id)).size,539);assert.equal(new Set(photos.map(p=>p.photo.sha256)).size,539);
 let structured=0,intro=0;for(const row of manifest.facilities){const proof=evidence.find(x=>x.row.id===row.id),p=photos.find(x=>x.id===row.id),stored=E.get(row);assert(stored);assert.equal(row.name,proof.tour.title.trim());assert.equal(row.lat,Number(proof.tour.yCoord));assert.equal(row.lng,Number(proof.tour.xCoord));assert.equal(P.get(row).sha256,p.photo.sha256);assert.equal(p.officialImage.originimgurl.replace(/^http:/,'https:'),p.photo.original);assert.equal(p.officialImage.cpyrhtDivCd,p.photo.rightsType);assert(['Type1','Type3'].includes(p.photo.rightsType));assert(P.figure(row).includes('object-fit:contain'));require('./helpers/photo-original.cjs')(p.photo);
  assert.equal(E.conditions({...row,description:row.description+' changed'}),null);assert.equal(E.intro({...row,description:row.description+' changed'}),null);assert.equal(E.intro({...row,address:'different branch'}),null);
  if(proof.pet){structured++;assert.deepEqual(E.conditions(row),proof.pet);assert(['전구역 동반가능','일부구역 동반가능'].includes(proof.pet.acmpyTypeCd));}else{intro++;assert.equal(E.conditions(row),null);assert(E.intro(row));assert.equal(stored.introAllowance.wholeAreaConfirmed,false);assert.equal(crypto.createHash('sha256').update(proof.tour.outl).digest('hex'),stored.introAllowance.originalTextSha256);assert(C.get(row).find(x=>x.label==='견종·크기 조건').value.startsWith('미확인'));assert(C.get(row).find(x=>x.label==='필수 준비물').value.startsWith('미확인'));assert(C.freshness(row,Date.parse('2026-10-20T23:59:00+09:00')).includes('공식 소개 대조'));assert(!/(?:동반|입장|입실|출입).{0,10}(?:불가|불가능|금지|할 수 없|가능하지 않|불허)/.test(stored.introAllowance.excerpt));}
  const html=fs.readFileSync('places/'+row.id+'/index.html','utf8');assert(html.includes(P.url(p.photo)));assert(html.includes('id="detail-conditions"'));assert(html.includes('2026-10-20'));assert(!html.includes('undefined'));
 }assert.equal(structured,100);assert.equal(intro,439);
 const names=new Set(manifest.facilities.map(x=>x.name));for(const denied of ['지평레포츠공원','포레포라','S STAY HOTEL','대북경','대왕암공원오토캠핑장','지리산구름정원'])assert(!names.has(denied));
});
test('introduction dates and links cannot survive changed identity or a future review date',()=>{
 const row=manifest.facilities.find(x=>E.intro(x)),record=E.get(row),before=record.introAllowance.checked;try{record.introAllowance.checked='2099-01-01';assert(!C.freshness(row,Date.parse('2026-10-20T23:59:00+09:00')).includes('2099'));}finally{record.introAllowance.checked=before;}assert(!C.panel({...row,description:'unrelated conditions'}).includes('공식 소개 대조'));
});
function meters(a,b){const r=Math.PI/180;return 12742000*Math.asin(Math.sqrt(Math.sin((b[0]-a[0])*r/2)**2+Math.cos(a[0]*r)*Math.cos(b[0]*r)*Math.sin((b[1]-a[1])*r/2)**2));}
test('two proposed courses use consecutive original pedestrian nodes with bounded permission and real photographs',()=>{
 assert.equal(manifest.courses.length,2);const context={CourseInfo:require('../course-info.js')};vm.createContext(context);for(const f of ['course-routes.js','course-expansion-300.js','course-expansion-20261009.js','course-expansion-20261009-night.js','course-expansion-20261017.js'])vm.runInContext(fs.readFileSync(f,'utf8'),context);const old=read('baseline-courses.json.gz');
 for(const c of manifest.courses){assert(!old.some(x=>x.id===c.id||x.name===c.name));assert(c.path.length>=10);assert.deepEqual([c.lat,c.lng],c.path[0]);assert.equal(c.diff,'미확인');assert(c.description.includes('공식 지정 산책 코스나 현장 답사 경로가 아닙니다'));assert(c.description.includes('전체 경로 사진이 아닙니다'));assert(Pet.get(c));assert(context.CourseRoutes.get(c)?.proposed);assert(!Pet.get(c).conditions['동반구분'].startsWith('전구역'));assert(Pet.get(c).conditions['동반구분'].includes('미확인'));let length=0;for(let i=0;i<c.path.length;i++){assert.deepEqual(c.path[i],routeProof.nodes[c.evidence.nodeIds[i]]);if(!i)continue;const a=c.evidence.nodeIds[i-1],b=c.evidence.nodeIds[i],w=routeProof.ways.find(w=>w.id===c.evidence.wayIds[i-1]);assert(w);assert(['footway','path','pedestrian','steps'].includes(w.tags.highway));assert(!['private','no','customers','permit'].includes(w.tags.access));assert.notEqual(w.tags.dog,'no');assert(w.nodes.some((n,j)=>j&&((w.nodes[j-1]===a&&n===b)||(w.nodes[j-1]===b&&n===a))));const d=meters(c.path[i-1],c.path[i]);assert(d<=120);length+=d;}assert(Math.abs(length-c.evidence.meters)<.01);const edited={...c,path:c.path.map(p=>[...p])};edited.path[1][0]+=.001;assert.equal(Pet.get(edited),null);assert.equal(context.CourseRoutes.get(edited),null);const p=CP.get(c);assert(p&&p.noCrop);assert.equal(crypto.createHash('sha256').update(fs.readFileSync('.'+p.src)).digest('hex'),p.sourceSha256);assert(routeProof.review.find(x=>x.name===c.evidence.place.title).insideBoundary);assert.equal(routeProof.review.find(x=>x.name===c.evidence.place.title).overlapAbove10PercentWithin25m.length,0);}
});
